def delete_project(store: dict[str, dict], project_id: str) -> None:
    """Remove a project. Authorization is enforced by the route layer before this is called."""
    store.pop(project_id, None)

import projects


def test_deletes_existing_project():
    store = {"p1": {"owner": "alice"}, "p2": {"owner": "bob"}}
    projects.delete_project(store, "p1")
    assert store == {"p2": {"owner": "bob"}}
